(** ** Abstract part (bb9_redir_fh_coq/abstract_fh*.v.in) *)

(** *** The token family *)

(** [lfr ds]: tokens D(d) = (10)^d 1, nearest-first, then blank. *)
Fixpoint lfr (ds : list nat) : side :=
  match ds with
  | [] => const 0
  | d :: t => [1;0]^^d *> 1 >> lfr t
  end.

(** Kf ds a r = 0^inf D(d_n) .. D(d_1) D(a) D(r) (10)^4 F> 0^inf  (r: accumulator; digits are tokens 3d+1). *)
Definition Kf (ds : list nat) (a r : nat) : Q * tape :=
  ([0;1]^^4 *> [1;0]^^r *> 1 >> [1;0]^^a *> 1 >> lfr ds) {{F}}> const 0.

Lemma pow_add : forall (xs : list Sym) n m Y, xs^^(n + m) *> Y = xs^^n *> xs^^m *> Y.
Proof. intros. rewrite lpow_add, Str_app_assoc. reflexivity. Qed.

Lemma pow_S : forall (xs : list Sym) n Y, xs^^(S n) *> Y = xs *> xs^^n *> Y.
Proof. intros. simpl. apply Str_app_assoc. Qed.

Lemma pow_mul : forall (xs : list Sym) k n Y, xs^^(k * n) *> Y = (xs^^k)^^n *> Y.
Proof.
  induction n; intros.
  - rewrite Nat.mul_0_r. reflexivity.
  - rewrite Nat.mul_succ_r, Nat.add_comm, pow_add, IHn.
    change ((xs^^k)^^(S n)) with (xs^^k ++ (xs^^k)^^n). rewrite Str_app_assoc. reflexivity.
Qed.

Lemma lfr_rep : forall d n t, lfr (repeat d n ++ t) = ([1;0]^^d ++ [1])^^n *> lfr t.
Proof.
  induction n; intros.
  - reflexivity.
  - cbn [repeat app lfr]. rewrite pow_S, Str_app_assoc, IHn. reflexivity.
Qed.

Lemma lfr_rep_nil : forall d n, lfr (repeat d n) = ([1;0]^^d ++ [1])^^n *> const 0.
Proof. intros. rewrite <- (app_nil_r (repeat d n)), lfr_rep. reflexivity. Qed.

Lemma lfr_ones : forall n t, lfr (repeat 1%nat n ++ t) = [1;0;1]^^n *> lfr t.
Proof. intros. rewrite lfr_rep. reflexivity. Qed.

(** *** Champion rules on raw tokens (generated lemmas FR1-FR3) *)

Lemma Kf_R1 : forall ds a r, Kf ds (3 + a) r -->+ Kf ds a (2 * r + 6).
Proof.
  intros. unfold Kf. replace (2 * r + 6) with (6 + 2 * r) by lia.
  rewrite (pow_add [1;0] 6 (2 * r)), (pow_mul [1;0] 2 r).
  exact (FR1 a r (lfr ds)).
Qed.

Lemma Kf_R2 : forall x t r, Kf ((3 + x) :: t) 1 r -->+ Kf (x :: t) (2 * r + 7) 0.
Proof.
  intros. unfold Kf. cbn [lfr]. replace (2 * r + 7) with (7 + 2 * r) by lia.
  rewrite (pow_add [1;0] 7 (2 * r)), (pow_mul [1;0] 2 r).
  exact (FR2 r x (lfr t)).
Qed.

Lemma Kf_R3 : forall M x t r,
  Kf (repeat 1%nat (S M) ++ (3 + x) :: t) 1 r -->+ Kf (repeat 1%nat M ++ (2 * r + 7) :: x :: t) 1 0.
Proof.
  intros. unfold Kf. rewrite !lfr_ones. cbn [lfr]. replace (2 * r + 7) with (7 + 2 * r) by lia.
  rewrite (pow_add [1;0] 7 (2 * r)), (pow_mul [1;0] 2 r).
  exact (FR3 M r x (lfr t)).
